+use std::io::{self, BufWriter, Write};
+
+const FIFTEEN_MINUTES: i64 = 15 * 60;
+const MINIMUM_BILLING_INCREMENT: i64 = 30 * 60;
+
+pub struct InvoiceCommand;
+
+fn billable_seconds(duration: i64) -> i64 {
+    let rounded = ((duration + FIFTEEN_MINUTES - 1) / FIFTEEN_MINUTES) * FIFTEEN_MINUTES;
+    rounded.max(MINIMUM_BILLING_INCREMENT)
+}
+
+fn project_totals(entries: &[TimeEntry]) -> Vec<(String, i64)> {
+    let mut totals = HashMap::<String, i64>::new();
+
+    for entry in entries {
+        if entry.billable && !entry.is_running() {
+            let project = entry
+                .project
+                .as_ref()
+                .map(|project| project.name.clone())
+                .unwrap_or_else(|| "No Project".to_string());
+            *totals.entry(project).or_default() += billable_seconds(entry.duration);
+        }
+    }
+
+    let mut totals: Vec<_> = totals.into_iter().collect();
+    totals.sort_by(|(left_name, left_total), (right_name, right_total)| {
+        right_total
+            .cmp(left_total)
+            .then_with(|| left_name.cmp(right_name))
+    });
+    totals
+}
+
+impl InvoiceCommand {
+    pub async fn execute(
+        api_client: impl ApiClient,
+        since: Option<String>,
+        until: Option<String>,
+    ) -> ResultWithDefaultError<()> {
+        let entries = if since.is_some() || until.is_some() {
+            let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
+            api_client.get_time_entries_filtered(since, until).await?
+        } else {
+            api_client.get_entities().await?.time_entries
+        };
+
+        let totals = project_totals(&entries);
+        let stdout = io::stdout();
+        let mut handle = BufWriter::new(stdout.lock());
+
+        if totals.is_empty() {
+            writeln!(handle, "(no data)").expect("failed to print");
+            return Ok(());
+        }
+
+        for (project, seconds) in &totals {
+            writeln!(handle, "{seconds}s  {project}").expect("failed to print");
+        }
+        let total_seconds: i64 = totals.iter().map(|(_, seconds)| seconds).sum();
+        writeln!(handle, "{total_seconds}s  Total").expect("failed to print");
+        Ok(())
+    }
+}
